from __future__ import annotations

import re
from csv import DictReader
from dataclasses import dataclass
from functools import cache
from typing import Literal

from ._html import css, html_escape
from ._locale import DATA_MOD

# A port of `fa()` from the R fontawesome package, which generates Font Awesome icons as inline
# SVGs. The icon data in `x_fontawesome.csv` and `x_fontawesome_aliases.csv` is generated by
# `scripts/generate_fontawesome_csv.py`.

__all__ = ("fa_svg",)

CSS_LENGTH_UNITS = (
    "cm",
    "mm",
    "in",
    "px",
    "pt",
    "pc",
    "em",
    "ex",
    "ch",
    "rem",
    "vw",
    "vh",
    "vmin",
    "vmax",
    "%",
)


@dataclass(frozen=True)
class FaIcon:
    name: str
    style: str
    full_name: str
    label: str
    width: int
    path: str


@dataclass(frozen=True)
class FaIconData:
    by_full_name: dict[str, FaIcon]
    # (an icon name can have more than one style, e.g., both a "solid" and a "regular" icon)
    by_name: dict[str, list[FaIcon]]
    aliases: dict[str, str]


@cache
def _get_icon_data() -> FaIconData:
    """Read the icon data (once, and only when an icon is first needed)."""

    by_full_name: dict[str, FaIcon] = {}
    by_name: dict[str, list[FaIcon]] = {}

    with (DATA_MOD / "x_fontawesome.csv").open(encoding="utf8") as f:
        for row in DictReader(f):
            icon = FaIcon(
                name=row["name"],
                style=row["style"],
                full_name=row["full_name"],
                label=row["label"],
                width=int(row["width"]),
                path=row["path"],
            )
            by_full_name[icon.full_name] = icon
            by_name.setdefault(icon.name, []).append(icon)

    with (DATA_MOD / "x_fontawesome_aliases.csv").open(encoding="utf8") as f:
        aliases = {row["alias"]: row["name"] for row in DictReader(f)}

    return FaIconData(by_full_name=by_full_name, by_name=by_name, aliases=aliases)


def get_icon(name: str, prefer_type: Literal["regular", "solid"] = "regular") -> FaIcon:
    """Get an icon from its full name (e.g., `"fas fa-star"`), short name or alias.

    A short name can refer to more than one style of icon. If one of those has the `prefer_type`
    style it is used, otherwise the first style is.
    """

    data = _get_icon_data()

    if name in data.by_full_name:
        return data.by_full_name[name]

    icons = data.by_name.get(name) or data.by_name.get(data.aliases.get(name, ""))

    if not icons:
        raise ValueError(f"The name provided ('{name}') does not correspond to a known icon.")

    for icon in icons:
        if icon.style == prefer_type:
            return icon
    return icons[0]


def _parse_length_unit(css_length: str) -> tuple[float, str]:
    """Split a CSS length (e.g., `"1.5em"`) into its value and unit."""

    if not re.fullmatch(r"[0-9]*\.?[0-9]+[a-z%]+", css_length):
        raise ValueError(
            "Values provided to `height` and `width` must have a numerical value followed by a "
            f"length unit (got '{css_length}')."
        )

    unit = re.sub(r"[0-9.]", "", css_length)

    if unit not in CSS_LENGTH_UNITS:
        raise ValueError(f"The provided CSS length unit ('{unit}') is not valid.")

    return float(css_length.removesuffix(unit)), unit


def _format_length(value: float, unit: str) -> str:
    # Written as R does (two decimal places at most, and no trailing `.0`)
    return str(round(value, 2)).removesuffix(".0") + unit


def fa_svg(
    name: str,
    fill: str | None = None,
    fill_opacity: str | float | None = None,
    stroke: str | None = None,
    stroke_width: str | None = None,
    stroke_opacity: str | float | None = None,
    height: str | None = None,
    width: str | None = None,
    margin_left: str | None = None,
    margin_right: str | None = None,
    vertical_align: str | None = None,
    position: str | None = None,
    title: str | None = None,
    prefer_type: Literal["regular", "solid"] = "regular",
    a11y: Literal["deco", "sem", "none"] = "deco",
) -> str:
    """Generate a Font Awesome icon as an SVG string.

    If neither `height` nor `width` is given, the icon is `1em` high and its width follows from its
    aspect ratio; if just one of them is given, the other follows from the aspect ratio. Setting
    both stretches the icon to fit. With `a11y="deco"` the icon is hidden from assistive
    technology; with `a11y="sem"` it is announced using `title` (or the icon's label, if `title`
    isn't given).
    """

    icon = get_icon(name, prefer_type=prefer_type)

    # The width of the icon, relative to its height (all icons have a viewBox height of 512)
    aspect = icon.width / 512

    stretch = height is not None and width is not None

    if height is None and width is None:
        height = "1em"
        width = _format_length(aspect, "em")
    elif height is not None and width is None:
        value, unit = _parse_length_unit(height)
        width = height if unit == "%" else _format_length(value * aspect, unit)
    elif height is None and width is not None:
        value, unit = _parse_length_unit(width)
        height = width if unit == "%" else _format_length(value / aspect, unit)
    elif height is not None and width is not None:
        _parse_length_unit(height)
        _parse_length_unit(width)

    attrs = f'viewBox="0 0 {icon.width} 512"'

    if stretch:
        attrs += ' preserveAspectRatio="none"'

    if a11y == "deco":
        attrs += ' aria-hidden="true" role="img"'
    elif a11y == "sem":
        title = icon.label if title is None else title
        attrs += f' aria-label="{html_escape(title, attr=True)}" role="img"'

    style = css(
        fill=fill or "currentColor",
        fill_opacity=fill_opacity,
        stroke=stroke,
        stroke_width=stroke_width,
        stroke_opacity=stroke_opacity,
        height=height,
        width=width,
        margin_left=margin_left or "auto",
        margin_right=margin_right or "auto",
        position=position or "relative",
        vertical_align=vertical_align or "-0.125em",
        overflow="visible",
    )

    title_tag = "" if title is None else f"<title>{html_escape(title)}</title>"

    return (
        f'<svg {attrs} class="fa" style="{html_escape(style or "", attr=True)}">'
        f'{title_tag}<path d="{icon.path}"/></svg>'
    )
